<script setup lang="ts">
const route=useRoute();const {request}=useAdminApi();const type=computed(()=>String(route.params.type));const titles:any={pages:'صفحات',posts:'مقالات',categories:'دسته‌بندی‌ها',gallery:'گالری',services:'خدمات',faqs:'سؤالات متداول',banners:'بنرها',homepage_sections:'بخش‌های صفحه اصلی'};
const rows=ref<any[]>([]),page=ref(1),totalPages=ref(1);const dialog=ref(false);const busy=ref(false);const error=ref(''),success=ref('');const editId=ref<number|null>(null);const uploadFile=ref<File|null>(null);const form=reactive({title:'',slug:'',body:'',image:'',is_active:true,status:'draft',published_at:'',seo_title:'',seo_description:'',sort_order:0,category_slug:''});
async function load(){error.value='';try{const r:any=await request(`/admin/content/${type.value}?page=${page.value}&per_page=20`);rows.value=r.data?.data||r.data||[];totalPages.value=Number(r.data?.last_page||1);}catch(e:any){error.value=e?.data?.message||'خطا در دریافت اطلاعات';}}
watch([type,page],load,{immediate:true});
function reset(){Object.assign(form,{title:'',slug:'',body:'',image:'',is_active:true,status:'draft',published_at:'',seo_title:'',seo_description:'',sort_order:0,category_slug:''});uploadFile.value=null;}
function add(){editId.value=null;reset();dialog.value=true;}
function edit(r:any){editId.value=r.id;Object.assign(form,{title:r.title,slug:r.slug,body:r.body||'',image:r.image||'',is_active:r.is_active,status:r.status|| (r.is_active?'published':'draft'),published_at:r.published_at?.slice(0,16)||'',seo_title:r.seo_title||'',seo_description:r.seo_description||'',sort_order:Number(r.sort_order||0),category_slug:r.extra?.category_slug||''});dialog.value=true;}
async function upload(){if(!uploadFile.value)return;busy.value=true;error.value='';try{const body=new FormData();body.append('image',uploadFile.value);const r:any=await request('/admin/gallery/upload',{method:'POST',body});form.image=r.data?.path||'';success.value='رسانه در backend ذخیره شد و به محتوا پیوند خورد.';}catch(e:any){error.value=e?.data?.message||'بارگذاری رسانه انجام نشد.';}finally{busy.value=false;}}
async function save(){if(busy.value)return;busy.value=true;error.value='';success.value='';try{const body:any={...form,is_active:form.status==='published',published_at:form.published_at?`${form.published_at}:00+03:30`:null,extra:form.category_slug?{category_slug:form.category_slug}:null};delete body.category_slug;await request(`/admin/content/${type.value}${editId.value?'/'+editId.value:''}`,{method:editId.value?'PUT':'POST',body});dialog.value=false;success.value='محتوا ذخیره شد.';await load();}catch(e:any){error.value=Object.values(e?.data?.errors||{}).flat().join(' · ')||e?.data?.message||'ذخیره محتوا انجام نشد.';}finally{busy.value=false;}}
async function remove(r:any){if(!confirm(`حذف «${r.title}»؟`))return;try{await request(`/admin/content/${type.value}/${r.id}`,{method:'DELETE'});await load();}catch(e:any){error.value=e?.data?.message||'خطا';}}
</script><template><main dir="rtl" class="admin-page"><header class="admin-page__header"><div><div class="admin-eyebrow">مدیریت محتوا</div><h1>{{titles[type]||type}}</h1><p>انتشار و زمان‌بندی از قرارداد واقعی backend استفاده می‌کند.</p></div><v-btn color="primary" @click="add">افزودن</v-btn></header><v-alert v-if="error" type="error" variant="tonal" class="mb-4">{{error}}</v-alert><v-alert v-if="success" type="success" variant="tonal" class="mb-4">{{success}}</v-alert><v-card class="admin-table-card"><div class="admin-table-scroll"><v-table><thead><tr><th>عنوان</th><th>اسلاگ</th><th>وضعیت</th><th>انتشار</th><th>SEO</th><th>عملیات</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.title}}</td><td>{{r.slug}}</td><td>{{r.status==='published'&&r.is_active?'منتشرشده':'پیش‌نویس'}}</td><td>{{r.published_at||'—'}}</td><td>{{r.seo_title||r.seo_description?'تنظیم‌شده':'—'}}</td><td><v-btn size="small" @click="edit(r)">ویرایش</v-btn><v-btn size="small" color="error" @click="remove(r)">حذف</v-btn></td></tr><tr v-if="!rows.length"><td colspan="6">محتوایی ثبت نشده است.</td></tr></tbody></v-table></div><div v-if="totalPages>1" class="admin-table-pagination"><v-btn :disabled="page<=1" @click="page--">قبلی</v-btn><span>صفحه {{page}} از {{totalPages}}</span><v-btn :disabled="page>=totalPages" @click="page++">بعدی</v-btn></div></v-card><v-dialog v-model="dialog" max-width="850" scrollable><v-card class="pa-6" dir="rtl"><h3 class="mb-4">{{editId?'ویرایش':'افزودن'}} · {{titles[type]||type}}</h3><v-text-field v-model="form.title" label="عنوان"/><v-text-field v-model="form.slug" label="اسلاگ انگلیسی"/><v-text-field v-model="form.image" label="مسیر رسانه (از آپلود انتخاب شود)"/><div class="d-flex align-center ga-2"><v-file-input v-model="uploadFile" accept="image/jpeg,image/png,image/webp,image/gif" label="بارگذاری تصویر (حداکثر ۵ مگابایت)"/><v-btn :disabled="!uploadFile" :loading="busy" @click="upload">بارگذاری</v-btn></div><v-textarea v-model="form.body" label="محتوا" rows="8"/><v-row><v-col cols="12" md="6"><v-text-field v-model="form.seo_title" label="عنوان SEO" maxlength="255"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.seo_description" label="توضیحات SEO" maxlength="500"/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.category_slug" label="اسلاگ دسته (اختیاری)"/></v-col><v-col cols="12" md="6"><v-text-field v-model.number="form.sort_order" type="number" min="0" label="ترتیب نمایش"/></v-col><v-col cols="12" md="6"><v-select v-model="form.status" :items="[{title:'پیش‌نویس',value:'draft'},{title:'انتشار',value:'published'}]" label="وضعیت انتشار"/></v-col><v-col v-if="form.status==='published'" cols="12" md="6"><v-text-field v-model="form.published_at" type="datetime-local" label="زمان انتشار (اختیاری)"/></v-col></v-row><div class="d-flex ga-3"><v-btn color="primary" :loading="busy" :disabled="!form.title||!form.slug" @click="save">ذخیره</v-btn><v-btn @click="dialog=false">انصراف</v-btn></div></v-card></v-dialog></main></template>
